DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='operator_garage_overview'; definition:=replace(definition,'s AS(SELECT h.*','ledger AS(SELECT h.* FROM public.garage_request_stats_hourly h JOIN own ON own.id=h.garage_id),s AS(SELECT h.*'); definition:=replace(definition,'sum(spend_usd) FROM s','sum(spend_usd) FROM ledger'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.signup_welcome_eligible(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_user_id AND p.created_at<=now()-interval '10 minutes' AND NOT EXISTS(SELECT 1 FROM public.api_keys k WHERE k.user_id=p.id) AND NOT EXISTS(SELECT 1 FROM public.garages g WHERE g.operator_id=p.id) AND NOT EXISTS(SELECT 1 FROM public.signup_welcome_notices n WHERE n.user_id=p.id AND n.sent_at IS NOT NULL)) $$;